+func TestBatchBytesWithPrivacyFilter_BatchesSingleCall(t *testing.T) {
+	fake := &fakeRuntime{spans: []Span{{Start: 0, End: 5, Label: "private_person"}}}
+	configureFakeOPF(t, fake, map[string]bool{"private_person": true})
+
