	}
	run("add", ".")
	run("commit", "-m", "Checkpoint: aaaaaaaaaaaa")

	// Commit 2: update same checkpoint (session_count 1→2) + add new file
	if err := os.WriteFile(filepath.Join(dir1, "metadata.json"),
